            reply = success(packet.id, result)
        except Exception as error:
            reply = failure(packet.id, error)
        self.journal.append(principal, packet, 'complete' if reply['ok'] else 'failed')
        return reply

    def batch(self, sid, values):
        self.sessions.resolve(sid)
        if not isinstance(values, list) or not 1 <= len(values) <= self.settings.batch_size:
            raise Invalid('batch')
        replies = []
        for value in values:
            replies.append(self.invoke(sid, value))
        return {'replies': replies}

    def history(self, sid, after=0, limit=16):
        _, principal = self.sessions.resolve(sid)
        require_scope(principal, 'read')
        return self.journal.page(principal, integer(after), integer(limit, 1, 64))

    def close_session(self, sid):
        return self.sessions.close(sid)

    def shutdown(self):
        self.closed = True
        self.sessions.rows.clear()

from dataclasses import dataclass
from .validation import text, object_value
from .errors import Invalid

@dataclass(frozen=True)
class Packet:
    id: str
    tool: str
    arguments: dict

    @classmethod
    def parse(cls, value):
        if not isinstance(value, dict):
            raise Invalid('packet')
        if set(value) - {'id', 'tool', 'arguments'}:
            raise Invalid('packet field')
        request_id = text(value.get('id', 'local'), 96)
        tool = text(value.get('tool'), 80)
        arguments = value.get('arguments', {})
        if not isinstance(arguments, dict):
            raise Invalid('packet arguments')
        return cls(request_id, tool, object_value(arguments))

import re
from .errors import Invalid

NAME = re.compile(r'[a-z][a-z0-9_-]{0,47}\Z')

def name(value):
    if not isinstance(value, str) or not NAME.fullmatch(value):
        raise Invalid('name')
    return value

def text(value, maximum=4096):
    if not isinstance(value, str) or len(value.encode('utf-8')) > maximum:
        raise Invalid('text')
    return value

def integer(value, low=0, high=1000000):
    if type(value) is not int or not low <= value <= high:
        raise Invalid('integer')
    return value

def object_value(value, depth=0):
    if depth > 8:
        raise Invalid('nesting')
    if value is None or type(value) in (bool, int):
        return value
    if isinstance(value, str):
        return text(value, 16384)
    if isinstance(value, list) and len(value) <= 64:
        return [object_value(v, depth + 1) for v in value]
    if isinstance(value, dict) and len(value) <= 64:
        if any(not isinstance(k, str) or len(k) > 64 for k in value):
            raise Invalid('object key')
        return {k: object_value(v, depth + 1) for k, v in value.items()}
    raise Invalid('object')
